import * as http from "node:http";
const srv = http.createServer(async (req, res) => {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  res.end(Buffer.concat(chunks));
});
function main(): void {
  srv.listen(0, "127.0.0.1", async () => {
    const r = await fetch(`http://127.0.0.1:${(srv.address() as any).port}/`, { method: "POST", body: "payload" });
    console.log(await r.text());
    const g = await fetch(`http://127.0.0.1:${(srv.address() as any).port}/`);
    console.log(JSON.stringify(await g.text()));
    srv.close();
  });
}
